"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[610],{6963:e=>{e.exports=JSON.parse('{"functions":[{"name":"get","desc":"Returns the current value without yielding.\\n\\nOn the client, errors if the value hasn\'t arrived yet. Call [Sencha.waitForReplicators] while loading, or use\\n[TemporaryPlayerReplicator:getAsync] or [TemporaryPlayerReplicator:observe] in code that may run earlier.\\n\\nOn the client, this includes pending predictions. [TemporaryPlayerReplicator:getConfirmed] returns the server\'s value\\nwithout them.","params":[{"name":"player","desc":"required on the server, left out on the client","lua_type":"Player?"}],"returns":[{"desc":"","lua_type":"T"}],"function_type":"method","source":{"line":168,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryPlayerReplicator.luau"}},{"name":"getAsync","desc":"Returns the current value, yielding until it\'s available. Server values always exist, so this only yields on the\\nclient.\\n\\nOn the client, this includes pending predictions. [TemporaryPlayerReplicator:getConfirmed] returns the server\'s value\\nwithout them.","params":[{"name":"player","desc":"required on the server, left out on the client","lua_type":"Player?"}],"returns":[{"desc":"","lua_type":"T"}],"function_type":"method","yields":true,"source":{"line":191,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryPlayerReplicator.luau"}},{"name":"set","desc":"Sets a player\'s value and sends it to them. Errors if the value doesn\'t match the replicator\'s type. Setting\\na primitive to the value it already has does nothing; setting a table always counts as a change.","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"value","desc":"","lua_type":"T"}],"returns":[],"function_type":"method","realm":["Server"],"source":{"line":211,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryPlayerReplicator.luau"}},{"name":"tryUpdate","desc":"Calls `callback` with a player\'s current value. If it returns `true` and a new value, the value is set as with\\n[TemporaryPlayerReplicator:set]; if it returns `false`, nothing changes. Returns what `callback` returned first.\\n\\n`callback` must not yield, so nothing else can change the value between reading and setting it.\\n\\n```lua\\nlocal didBuy = CurrencyNetwork.coinsReplicator:tryUpdate(player, function(coins)\\n\\tif coins < 10 then\\n\\t\\treturn false\\n\\tend\\n\\treturn true, coins - 10\\nend)\\n```","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"callback","desc":"","lua_type":"(value: T) -> (boolean, T?)"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"method","realm":["Server"],"source":{"line":239,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryPlayerReplicator.luau"}},{"name":"applyIncrementalUpdate","desc":"Applies `patch` to a player\'s value with the incremental config\'s `apply`, then sends only the patch to them.\\nErrors if the patch or the new value doesn\'t match its type, or if the replicator has no incremental config. An\\nempty table patch does nothing.","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"patch","desc":"","lua_type":"P"}],"returns":[],"function_type":"method","realm":["Server"],"source":{"line":266,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryPlayerReplicator.luau"}},{"name":"onChanged","desc":"Calls `callback` when the value changes, not for the initial value. On the server this fires for any player whose\\nvalue changes; on the client `player` is always the local player.\\n\\nOn the server, the change is sent to clients before `callback` runs, so anything it changes in response reaches\\nclients after the change that caused it.\\n\\nOn the client, this also fires when a prediction is made, and again if it\'s rolled back. Use\\n[TemporaryPlayerReplicator:onConfirmedChanged] to only hear about the server\'s changes.","params":[{"name":"callback","desc":"","lua_type":"(player: Player, newValue: T, oldValue: T) -> ()"}],"returns":[{"desc":"","lua_type":"Disconnect"}],"function_type":"method","source":{"line":317,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryPlayerReplicator.luau"}},{"name":"observe","desc":"Calls `callback` with the current value right away if it has arrived (otherwise when it arrives), then on\\nevery change. `oldValue` is the value before the change, or `nil` for the first call.\\n\\n```lua\\nCurrencyNetwork.coinsReplicator:observe(function(coins, oldCoins)\\n\\tprint(`coins: {oldCoins} -> {coins}`) -- oldCoins is nil the first time\\nend)\\n```\\n\\nThis includes predictions: it fires when a prediction is made, and again if it\'s rolled back.","params":[{"name":"callback","desc":"","lua_type":"(newValue: T, oldValue: T?) -> ()"}],"returns":[{"desc":"","lua_type":"Disconnect"}],"function_type":"method","realm":["Client"],"source":{"line":353,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryPlayerReplicator.luau"}},{"name":"onUpdateReceived","desc":"Calls `callback` for each patch received, after the value is updated. Only replicators with an incremental\\nconfig receive patches; calling this on one without errors.\\n\\nWhole values (the first value, or a `set`) don\'t fire this; use\\n[TemporaryPlayerReplicator:onChanged] to see every change.\\n\\nPatches always come from the server: predictions don\'t fire this, and `newValue` and `oldValue` are the\\nserver\'s values.","params":[{"name":"callback","desc":"","lua_type":"(newValue: T, oldValue: T, patch: P) -> ()"}],"returns":[{"desc":"","lua_type":"Disconnect"}],"function_type":"method","realm":["Client"],"source":{"line":378,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryPlayerReplicator.luau"}},{"name":"getObservable","desc":"Returns an [ObservableValue](https://jdevon.github.io/observable-value/) that follows the replicated value,\\nfor code that works with ObservableValues, like the\\n[ReactObservableValue](https://github.com/JDevon/react-observable-value) hooks. Calling this again returns the same\\none. Setting it doesn\'t change the replicated value. Errors if the value hasn\'t arrived yet.\\n\\n```lua\\nlocal coins = ReactObservableValue.useObservableValue(CurrencyNetwork.coinsReplicator:getObservable())\\n```\\n\\nThe observable includes pending predictions, like [TemporaryPlayerReplicator:get].","params":[],"returns":[{"desc":"","lua_type":"ObservableValue<T>"}],"function_type":"method","realm":["Client"],"source":{"line":404,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryPlayerReplicator.luau"}},{"name":"getConfirmed","desc":"Returns the value the server sent, without any pending predictions. [TemporaryPlayerReplicator:get] returns the\\npredicted value while a prediction is pending; use this when code must only act on what the server has confirmed.\\nErrors if the value hasn\'t arrived yet.","params":[],"returns":[{"desc":"","lua_type":"T"}],"function_type":"method","realm":["Client"],"source":{"line":422,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryPlayerReplicator.luau"}},{"name":"onConfirmedChanged","desc":"Calls `callback` when the server\'s value changes, not for predictions or the initial value. `player` is always the\\nlocal player.\\n\\n[TemporaryPlayerReplicator:onChanged] also fires for predictions, and again if a wrong prediction is rolled back.\\nUse this instead for effects that should only change for confirmed values:\\n\\n```lua\\nCurrencyNetwork.coinsReplicator:onConfirmedChanged(function(_player, coins, oldCoins)\\n\\tif coins > oldCoins then\\n\\t\\tplayCoinsGainedSound() -- never plays for a prediction that gets rolled back\\n\\tend\\nend)\\n```","params":[{"name":"callback","desc":"","lua_type":"(player: Player, newValue: T, oldValue: T) -> ()"}],"returns":[{"desc":"","lua_type":"Disconnect"}],"function_type":"method","realm":["Client"],"source":{"line":449,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryPlayerReplicator.luau"}},{"name":"prediction","desc":"Builds a prediction for this replicator. The returned prediction can be used with a predicted remote call such as\\n`invokeServerPredicted` or `fireServerPredicted`. While the call is pending, [TemporaryPlayerReplicator:get],\\n[TemporaryPlayerReplicator:observe] and [TemporaryPlayerReplicator:onChanged] show the value with the prediction\\napplied; it\'s removed when the server confirms the call.\\n\\n`predict` is either a function that returns the predicted value, or a patch on a replicator with an incremental\\nconfig. A patch is applied with the config\'s `apply`, the same way the server\'s patches are.\\n\\n```lua\\nCurrencyNetwork.buyItemRemote:invokeServerPredicted({\\n\\tCurrencyNetwork.coinsReplicator:prediction(function(coins)\\n\\t\\treturn coins - 10\\n\\tend),\\n}, \\"sword\\")\\n```","params":[{"name":"predict","desc":"","lua_type":"((value: T) -> T) | P"}],"returns":[{"desc":"","lua_type":"Prediction"}],"function_type":"method","realm":["Client"],"source":{"line":483,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryPlayerReplicator.luau"}},{"name":"isLoaded","desc":"Returns whether the value has arrived from the server.","params":[],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"method","realm":["Client"],"source":{"line":500,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryPlayerReplicator.luau"}}],"properties":[],"types":[],"name":"TemporaryPlayerReplicator","desc":"One value per player that the server keeps in memory, created with `Sencha.temporaryReplicator.player`. Each\\nplayer\'s value is sent only to that player, starts as the default value, and is cleared when they leave.","source":{"line":25,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryPlayerReplicator.luau"}}')}}]);